import heapq


def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs:
        return 0

    times = sorted({t for start, end, _ in jobs for t in (start, end)})
    time_to_idx = {t: i for i, t in enumerate(times)}
    n = len(times)
    sink = n - 1

    graph: list[list[list[int]]] = [[] for _ in range(n)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        graph[u].append([v, cap, cost, len(graph[v])])
        graph[v].append([u, 0, -cost, len(graph[u]) - 1])

    for i in range(n - 1):
        add_edge(i, i + 1, k, 0)

    for start, end, pay in jobs:
        add_edge(time_to_idx[start], time_to_idx[end], 1, -pay)

    inf = 10**18
    pot = [inf] * n
    pot[0] = 0
    for u in range(n):
        pu = pot[u]
        if pu == inf:
            continue
        for v, cap, cost, _ in graph[u]:
            if cap > 0 and pu + cost < pot[v]:
                pot[v] = pu + cost

    flow = 0
    total_cost = 0
    pv = [-1] * n
    pe = [-1] * n

    while flow < k:
        dist = [inf] * n
        dist[0] = 0
        pq = [(0, 0)]

        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            pu = pot[u]
            for idx, (v, cap, cost, _) in enumerate(graph[u]):
                if cap > 0:
                    nd = d + cost + pu - pot[v]
                    if nd < dist[v]:
                        dist[v] = nd
                        pv[v] = u
                        pe[v] = idx
                        heapq.heappush(pq, (nd, v))

        if dist[sink] == inf:
            break

        for i in range(n):
            if dist[i] < inf:
                pot[i] += dist[i]

        if pot[sink] >= 0:
            break

        push = k - flow
        v = sink
        while v != 0:
            u = pv[v]
            cap = graph[u][pe[v]][1]
            if cap < push:
                push = cap
            v = u

        flow += push
        total_cost += push * pot[sink]

        v = sink
        while v != 0:
            u = pv[v]
            edge = graph[u][pe[v]]
            edge[1] -= push
            graph[v][edge[3]][1] += push
            v = u

    return -total_cost
